import { DashboardPage } from "@/components/dashboard-page";

export default function Page() {
  return <DashboardPage />;
}

/**
 * Named value formatters.
 *
 * Panels take `format="money"` rather than a `formatter` function, because the
 * installed entry point of this block is `app/dashboard/page.tsx` — a server
 * component. A function cannot cross that boundary: React rejects it at render
 * time. A block that taught `formatter={(v) => …}` would teach a pattern that
 * breaks the moment someone installs it.
 */

export type ValueFormat = "compact" | "money" | "number" | "percent";

const NUMBER = new Intl.NumberFormat("en-US");
const COMPACT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 1,
  notation: "compact",
});
const MONEY = new Intl.NumberFormat("en-US", {
  currency: "USD",
  maximumFractionDigits: 0,
  style: "currency",
});
const PERCENT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 1,
  style: "percent",
});

const FORMATTERS: Record<ValueFormat, (value: number) => string> = {
  compact: (value) => COMPACT.format(value),
  money: (value) => MONEY.format(value),
  number: (value) => NUMBER.format(value),
  percent: (value) => PERCENT.format(value),
};

/**
 * `null` stays `null` all the way to the em dash.
 *
 * Coercing with `Number(value)` turns an absent measurement into `0`, which
 * then prints as "$0" or "0%" — a reading the data never took. The distinction
 * between "nothing happened" and "we did not measure" is worth the extra
 * branch.
 */
export function toValue(value: unknown): number | null {
  if (value == null) {
    return null;
  }
  const numeric = typeof value === "number" ? value : Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

export function formatValue(
  value: unknown,
  format: ValueFormat = "number"
): string {
  const numeric = toValue(value);
  return numeric === null ? "—" : FORMATTERS[format](numeric);
}

/**
 * The chart layer for this block, ported from shadcn's `chart.tsx`.
 *
 * Vendored into the block rather than added to `@keystoneui/react` on purpose:
 * it needs recharts, and the library stays dependency-light. A block may carry
 * npm dependencies of its own -- `tickets-01` already does, with `@dnd-kit`.
 *
 * Most of the value is the ~20 `[&_.recharts-*]` overrides on `ChartContainer`,
 * which make recharts' hardcoded `#ccc` and `#fff` marks respect the theme.
 * That list is archaeology, not something to re-derive.
 *
 * Two changes from upstream shadcn, both load-bearing:
 *
 *  - `aspect-auto`, not `aspect-video`. Under an explicit pixel height the
 *    upstream class produces a 462px floor and a horizontal document
 *    scrollbar.
 *  - `min-w-0` added, because a chart is a grid or flex child and those
 *    default to `min-content`.
 *
 * `ChartLegend`/`ChartLegendContent` are dropped: `series-legend.tsx` ships a
 * toggleable legend, so recharts' own `<Legend>` never mounts, and leaving the
 * dead path in would mean two legends to pick between.
 */
"use client";

import * as React from "react";
import type { TooltipValueType } from "recharts";
import * as RechartsPrimitive from "recharts";
import { cn } from "@/lib/utils";

/**
 * Format: { THEME_NAME: CSS_SELECTOR }.
 *
 * Upstream emits a `.dark [data-chart=id]` block as well, so a config can carry
 * a literal colour per mode. Ours never does -- `seriesColor()` returns a
 * `var(--chart-N)` *reference*, and the token already re-steps for dark -- so
 * the second block would be textually identical to the first. One entry.
 */
const THEMES = { light: "" } as const;

const INITIAL_DIMENSION = { width: 320, height: 200 } as const;
type TooltipNameType = number | string;

export type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode;
    icon?: React.ComponentType;
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>;

interface ChartContextProps {
  config: ChartConfig;
}

const ChartContext = React.createContext<ChartContextProps | null>(null);

function useChart() {
  const context = React.useContext(ChartContext);

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />");
  }

  return context;
}

function ChartContainer({
  id,
  className,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig;
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"];
  initialDimension?: {
    width: number;
    height: number;
  };
}) {
  const uniqueId = React.useId();
  const chartId = `chart-${id ?? uniqueId.replace(/:/g, "")}`;

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "flex aspect-auto min-w-0 justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-sector]:outline-hidden [&_.recharts-surface]:outline-hidden",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer
          initialDimension={initialDimension}
        >
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme ?? config.color
  );

  if (!colorConfig.length) {
    return null;
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ??
      itemConfig.color;
    return color ? `  --color-${key}: ${color};` : null;
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  );
};

const ChartTooltip = RechartsPrimitive.Tooltip;

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  color,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean;
    hideIndicator?: boolean;
    indicator?: "line" | "dot" | "dashed";
    nameKey?: string;
    labelKey?: string;
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart();

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null;
    }

    const [item] = payload;
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`;
    const itemConfig = getPayloadConfigFromPayload(config, item, key);
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : itemConfig?.label;

    if (labelFormatter) {
      return (
        <div className={cn("font-medium", labelClassName)}>
          {labelFormatter(value, payload)}
        </div>
      );
    }

    if (!value) {
      return null;
    }

    return <div className={cn("font-medium", labelClassName)}>{value}</div>;
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ]);

  if (!(active && payload?.length)) {
    return null;
  }

  const nestLabel = payload.length === 1 && indicator !== "dot";

  return (
    <div
      className={cn(
        "grid min-w-32 items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl",
        className
      )}
    >
      {nestLabel ? null : tooltipLabel}
      <div className="grid gap-1.5">
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`;
            const itemConfig = getPayloadConfigFromPayload(config, item, key);
            const indicatorColor = color ?? item.payload?.fill ?? item.color;

            return (
              <div
                key={index}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center"
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-[2px] border-(--color-border) bg-(--color-bg)",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            }
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center"
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label ?? item.name}
                        </span>
                      </div>
                      {item.value != null && (
                        <span className="font-medium font-mono text-foreground tabular-nums">
                          {typeof item.value === "number"
                            ? item.value.toLocaleString()
                            : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            );
          })}
      </div>
    </div>
  );
}

function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return;
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined;

  let configLabelKey: string = key;

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string;
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string;
  }

  return configLabelKey in config ? config[configLabelKey] : config[key];
}

export { ChartContainer, ChartStyle, ChartTooltip, ChartTooltipContent };

"use client";

import { useMemo, useState } from "react";

import { DashboardToolbar } from "@/components/dashboard-toolbar";
import { KpiRow } from "@/components/kpi-row";
import {
  metrics,
  type PageRow,
  type Range,
  REVENUE_SERIES,
  revenueByWeek,
  sessionsByWeek,
  topPages,
  weeksFor,
} from "@/components/mock-analytics";
import { RevenueTrendCard } from "@/components/revenue-trend-card";
import { SessionsCard } from "@/components/sessions-card";
import {
  type PageSortKey,
  type SortDirection,
  TopPagesPanel,
} from "@/components/top-pages-panel";
import { useReducedMotion } from "@/components/use-reduced-motion";

const PAGE_SIZE = 5;

/**
 * Every piece of state lives here; the panels below are presentational and
 * take callbacks. Same architecture as `tickets-01`, and the reason a block is
 * readable at all — state scattered across panels is what makes a dashboard
 * impossible to follow.
 */
export function DashboardPage() {
  const reducedMotion = useReducedMotion();

  const [range, setRange] = useState<Range>("12w");
  const [hidden, setHidden] = useState<ReadonlySet<string>>(new Set());
  const [sort, setSort] = useState<{
    direction: SortDirection;
    key: PageSortKey;
  } | null>({ direction: "desc", key: "views" });
  const [pageIndex, setPageIndex] = useState(0);

  const weeks = weeksFor(range);
  const revenue = useMemo(() => revenueByWeek.slice(-weeks), [weeks]);
  const sessions = useMemo(() => sessionsByWeek.slice(-weeks), [weeks]);

  const sortedPages = useMemo(() => {
    if (!sort) {
      return topPages;
    }
    const factor = sort.direction === "asc" ? 1 : -1;
    return [...topPages].sort((a, b) => {
      const left = a[sort.key];
      const right = b[sort.key];
      if (typeof left === "string" && typeof right === "string") {
        return left.localeCompare(right) * factor;
      }
      return ((left as number) - (right as number)) * factor;
    });
  }, [sort]);

  const pageCount = Math.max(1, Math.ceil(sortedPages.length / PAGE_SIZE));
  const pageRows: readonly PageRow[] = sortedPages.slice(
    pageIndex * PAGE_SIZE,
    pageIndex * PAGE_SIZE + PAGE_SIZE
  );

  const toggleSeries = (key: string) => {
    setHidden((current) => {
      const next = new Set(current);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  };

  // Unsorted -> desc -> asc -> unsorted. A new column starts descending, which
  // is what you want for a metric.
  const cycleSort = (key: PageSortKey) => {
    setPageIndex(0);
    setSort((current) => {
      if (current?.key !== key) {
        return { direction: "desc", key };
      }
      if (current.direction === "desc") {
        return { direction: "asc", key };
      }
      return null;
    });
  };

  return (
    <div className="flex min-h-svh w-full flex-col bg-background">
      <div className="mx-auto flex w-full max-w-[1400px] flex-1 flex-col gap-6 px-4 py-6 sm:px-6 lg:px-8">
        <DashboardToolbar
          onRangeChange={(next) => {
            setRange(next);
            setPageIndex(0);
          }}
          range={range}
        />

        <KpiRow metrics={metrics} />

        <section className="grid gap-4 lg:grid-cols-3 [&>*]:min-w-0">
          <RevenueTrendCard
            data={revenue}
            hidden={hidden}
            onToggle={toggleSeries}
            reducedMotion={reducedMotion}
            series={REVENUE_SERIES}
          />
          <SessionsCard data={sessions} reducedMotion={reducedMotion} />
        </section>

        <TopPagesPanel
          onPageIndexChange={setPageIndex}
          onSort={cycleSort}
          pageCount={pageCount}
          pageIndex={pageIndex}
          rows={pageRows}
          sort={sort}
        />
      </div>
    </div>
  );
}

"use client";

import { DownloadIcon, InfoIcon } from "lucide-react";
import { useId, useState } from "react";
import { RANGES, type Range } from "@/components/mock-analytics";
import { Button } from "@/components/ui/button";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

/**
 * The accessible info-tip pattern: Base UI's tooltip wires no
 * `aria-describedby` and is mouse-only, so the text lives in an always-present
 * `sr-only` span, the popup is `aria-hidden` to avoid being read twice, and a
 * controlled click toggle (with `closeOnClick={false}`) makes it work on touch.
 */
function InfoTip({ content, label }: { content: string; label: string }) {
  const descriptionId = useId();
  const [open, setOpen] = useState(false);

  return (
    <>
      <Tooltip onOpenChange={setOpen} open={open}>
        <TooltipTrigger
          closeOnClick={false}
          render={
            <button
              aria-describedby={descriptionId}
              aria-label={`${label} definition`}
              className="inline-flex cursor-help items-center rounded-sm text-muted-foreground focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2 [&_svg:not([class*='size-'])]:size-3.5 [&_svg]:pointer-events-none [&_svg]:shrink-0"
              onClick={() => setOpen((previous) => !previous)}
              type="button"
            />
          }
        >
          <InfoIcon aria-hidden="true" />
        </TooltipTrigger>
        <TooltipContent aria-hidden="true" className="max-w-64">
          {content}
        </TooltipContent>
      </Tooltip>
      <span className="sr-only" id={descriptionId}>
        {content}
      </span>
    </>
  );
}

interface DashboardToolbarProps {
  onRangeChange: (range: Range) => void;
  range: Range;
}

export function DashboardToolbar({
  onRangeChange,
  range,
}: DashboardToolbarProps) {
  return (
    // min-w-0 flex-1 on the text column so a long title truncates instead of
    // pushing the actions off-screen; shrink-0 flex-wrap so the actions never
    // squash; items-end so they align to the bottom of the description.
    <header className="flex flex-wrap items-end justify-between gap-4">
      <div className="min-w-0 flex-1">
        <h1 className="font-semibold text-2xl tracking-tight">Analytics</h1>
        <p className="mt-1 inline-flex items-center gap-1.5 text-muted-foreground text-sm">
          Weekly performance across acquisition channels
          <InfoTip
            content="Revenue is attributed on a last-touch basis and excludes refunds. Sessions are de-duplicated per visitor per day."
            label="Attribution"
          />
        </p>
      </div>
      <div className="flex shrink-0 flex-wrap items-center gap-2">
        <ToggleGroup
          aria-label="Reporting range"
          onValueChange={(next) => {
            // The group is array-valued; take the last pressed item and keep
            // the control single-select.
            const last = next.at(-1);
            if (last && (RANGES as readonly string[]).includes(last)) {
              onRangeChange(last as Range);
            }
          }}
          value={[range]}
          variant="outline"
        >
          {RANGES.map((option) => (
            <ToggleGroupItem key={option} value={option}>
              {option}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
        <Button size="sm" variant="outline">
          <DownloadIcon data-icon="inline-start" />
          Export
        </Button>
      </div>
    </header>
  );
}

"use client";

import type { Metric } from "@/components/mock-analytics";
import { Card, CardContent } from "@/components/ui/card";
import { StatDelta, StatValue } from "@/components/ui/stat";

export function KpiRow({ metrics }: { metrics: readonly Metric[] }) {
  return (
    // [&>*]:min-w-0 is load-bearing: grid children resolve to min-content, so
    // one long value would push its track open and give the page a horizontal
    // scrollbar.
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4 [&>*]:min-w-0">
      {metrics.map((metric) => (
        <Card key={metric.label} size="sm" variant="outline">
          <CardContent className="flex flex-col gap-1">
            <div className="font-medium text-muted-foreground text-xs">
              {metric.label}
            </div>
            <StatValue>
              {metric.value}
              {metric.delta === null ? null : (
                <StatDelta direction={metric.direction} value={metric.delta}>
                  {metric.deltaLabel}
                </StatDelta>
              )}
            </StatValue>
            <div className="text-muted-foreground text-xs">
              {metric.sublabel}
            </div>
          </CardContent>
        </Card>
      ))}
    </section>
  );
}

import type { SeriesDef } from "@/components/series-legend";

/**
 * Fixture data.
 *
 * Deterministic on purpose — no `Math.random()`. Chromatic diffs this block on
 * every commit, and the overflow test measures its layout; either would be
 * unusable against output that changes on each render.
 */

export interface RevenuePoint {
  direct: number;
  organic: number;
  other: number;
  paid: number;
  referral: number;
  week: string;
}

export interface ChannelPoint {
  sessions: number;
  week: string;
}

export interface PageRow {
  bounce: number;
  conversion: number;
  path: string;
  views: number;
}

export interface Metric {
  delta: number | null;
  deltaLabel: string | null;
  direction: "down-is-good" | "neutral" | "up-is-good";
  label: string;
  sublabel: string;
  value: string;
}

export const REVENUE_SERIES: readonly SeriesDef[] = [
  { color: 1, key: "organic", label: "Organic" },
  { color: 2, key: "direct", label: "Direct" },
  { color: 3, key: "referral", label: "Referral" },
  { color: 4, key: "paid", label: "Paid" },
  // Not a category — a fold of everything too small to name. A categorical hue
  // here would claim a channel that does not exist.
  { key: "other", label: "Other", token: "muted-foreground" },
];

const WEEKS = [
  "Jun 2",
  "Jun 9",
  "Jun 16",
  "Jun 23",
  "Jun 30",
  "Jul 7",
  "Jul 14",
  "Jul 21",
  "Jul 28",
  "Aug 4",
  "Aug 11",
  "Aug 18",
];

// A fixed multiplier per week, so the shape is varied but reproducible.
const SHAPE = [
  0.82, 0.88, 0.94, 0.91, 1.02, 1.08, 1.04, 1.14, 1.19, 1.12, 1.26, 1.31,
];

export const revenueByWeek: readonly RevenuePoint[] = WEEKS.map(
  (week, index) => {
    const factor = SHAPE[index];
    const round = (base: number) => Math.round(base * factor);
    return {
      direct: round(5400),
      organic: round(8200),
      other: round(900),
      paid: round(3100),
      referral: round(2600),
      week,
    };
  }
);

export const sessionsByWeek: readonly ChannelPoint[] = WEEKS.map(
  (week, index) => ({
    sessions: Math.round(18_400 * SHAPE[index]),
    week,
  })
);

export const topPages: readonly PageRow[] = [
  { bounce: 0.31, conversion: 0.048, path: "/pricing", views: 48_210 },
  {
    bounce: 0.52,
    conversion: 0.011,
    path: "/blog/scaling-postgres",
    views: 31_884,
  },
  { bounce: 0.28, conversion: 0.062, path: "/docs/quickstart", views: 27_450 },
  { bounce: 0.44, conversion: 0.019, path: "/changelog", views: 19_003 },
  { bounce: 0.61, conversion: 0.004, path: "/blog/hiring", views: 15_772 },
  { bounce: 0.24, conversion: 0.081, path: "/signup", views: 12_940 },
  { bounce: 0.38, conversion: 0.026, path: "/integrations", views: 9812 },
  { bounce: 0.47, conversion: 0.014, path: "/about", views: 7106 },
];

export const metrics: readonly Metric[] = [
  {
    delta: 0.124,
    deltaLabel: "+12.4%",
    direction: "up-is-good",
    label: "Revenue",
    sublabel: "vs previous 12 weeks",
    value: "$248,910",
  },
  {
    delta: 0.081,
    deltaLabel: "+8.1%",
    direction: "up-is-good",
    label: "Sessions",
    sublabel: "220,800 total",
    value: "18.4k / wk",
  },
  {
    // Falling is the improvement here — the tile the `direction` prop exists
    // for. It renders green, with a down arrow.
    delta: -0.052,
    deltaLabel: "-5.2%",
    direction: "down-is-good",
    label: "Bounce rate",
    sublabel: "across all pages",
    value: "38.4%",
  },
  {
    delta: null,
    deltaLabel: null,
    direction: "neutral",
    label: "Active accounts",
    sublabel: "no prior period",
    value: "1,204",
  },
];

export const RANGES = ["4w", "12w", "26w"] as const;
export type Range = (typeof RANGES)[number];

/** Trailing slice of the fixture, so the range control does something real. */
export function weeksFor(range: Range): number {
  if (range === "4w") {
    return 4;
  }
  return range === "12w" ? 12 : WEEKS.length;
}

